package com.javacodingagent.bootstrap;
import io.micrometer.core.instrument.*;
public class AgentMetrics { private final MeterRegistry registry; public AgentMetrics(MeterRegistry registry) { this.registry = registry; } public void taskStarted() { registry.counter("agent_task_total").increment(); } public void taskSucceeded() { registry.counter("agent_task_success_total").increment(); } public void taskFailed() { registry.counter("agent_task_failure_total").increment(); } public Timer.Sample startTimer() { return Timer.start(registry); } public void finishTask(Timer.Sample sample) { sample.stop(registry.timer("agent_task_duration")); } public void modelCall() { registry.counter("agent_model_call_total").increment(); } public void toolCall(boolean success) { registry.counter("agent_tool_call_total").increment(); if (!success) registry.counter("agent_tool_failure_total").increment(); } public void testRun() { registry.counter("agent_test_execution_total").increment(); } public void repair() { registry.counter("agent_repair_attempt_total").increment(); } public void tokens(long count) { registry.counter("agent_token_usage_total").increment(count); } }
